    trailer_url: 'https://www.youtube.com/watch?v=NKYea63tQmI',
    description_ar: 'يستيقظ معلم العلوم ريلاند جريس على متن سفينة فضائية على بعد سنوات ضوئية من الأرض فاقدًا للذاكرة. مع استعادة ذاكرته، يكتشف مهمته: حل لغز المادة الغامضة التي تتسبب في احتضار الشمس وإنقاذ الأرض من الانقراض.',
    description_en: 'Science teacher Ryland Grace wakes up on a spaceship light years from home with no recollection of who he is or how he got there. As his memory returns, he begins to uncover his mission: solve the riddle of the mysterious substance causing the sun to die out. He must call on his scientific knowledge and unorthodox ideas to save everything on Earth from extinction.',
    description_fr: 'Un professeur de sciences, Ryland Grace, se réveille à bord d\'un vaisseau spatial à des années-lumière de la Terre, sans aucun souvenir de son identité ni de sa présence à bord. Sa mission se dévoile peu à peu: résoudre l\'énigme d\'une substance mystérieuse menaçant le soleil et, par conséquent, la Terre.',
    description_es: 'El profesor de ciencias Ryland Grace se despierta en una nave espacial a años luz de la Tierra sin recordar quién es ni cómo llegó allí. A medida que recuerda, descubre su misión: resolver el enigma de una sustancia misteriosa que está matando al sol y salvar a la Tierra de la extinción.',
    description_tr: 'Fen bilgisi öğretmeni Ryland Grace, kim olduğunu veya oraya nasıl geldiğini hatırlamadan, Dünya\'dan ışık yılları uzaklıkta bir uzay gemisinde uyanır. Hafızası yerine geldikçe, görevinin gizemli bir maddenin güneşi yok etmesinin gizemini çözmek ve Dünya\'yı yok olmaktan kurtarmak olduğunu keşfeder.',
    description_de: 'Der Naturwissenschaftslehrer Ryland Grace erwacht auf einem Raumschiff, Lichtjahre von der Erde entfernt, ohne Erinnerung daran, wer er ist oder wie er dorthin gekommen ist. Als seine Erinnerung zurückkehrt, deckt er seine Mission auf: das Rätsel der mysteriösen Substanz zu lösen, die die Sonne zum Sterben bringt, und die Erde vor dem Aussterben zu retten.',
    description_ja: '科学教師のライランド・グレースは、自分が誰なのか、どうしてそこにいるのかをまったく覚えていないまま、地球から光年離れた宇宙船の中で目を覚ます。記憶が戻るにつれて、彼は自分の使命を明らかにします。太陽を死滅させている謎の物質の謎を解き、地球を絶滅から救うのです。',
    description_pt: 'O professor de ciências Ryland Grace acorda numa nave espacial a anos-luz da Terra, sem se lembrar de quem é ou de como chegou lá. À medida que a sua memória regressa, ele começa a descobrir a sua missão: resolver o enigma da substância misteriosa que está a causar a morte do sol e salvar a Terra da extinção.',
