    description_ar: 'في هذه التكملة الملحمية لملحمة كورليوني، نشاهد فيتو كورليوني الشاب يكبر في صقلية ونيويورك في العقد الثاني من القرن العشرين. وفي الخمسينات، يحاول مايكل كورليوني توسيع إمبراطورية العائلة لتشمل لاس فيغاس وهوليوود وكوبا.',
