    id: '66', slug: 'the-punisher-one-last-kill', title: 'The Punisher: One Last Kill', title_ar: 'ذا بانشر: مهمة واحدة أخيرة', year: 2026,
    director: 'Reinaldo Marcus Green', director_ar: 'Reinaldo Marcus Green',
    cast: ['Jon Bernthal', 'Deborah Ann Woll', 'Jason R. Moore', 'Judith Light', 'Kelli Barrett', 'Andre Royo'],
