    id: '72', slug: 'gabriel-s-inferno', title: 'Gabriel\'s Inferno', title_ar: 'Gabriel\'s Inferno', year: 2020,
    director: 'Tosca Musk', director_ar: 'Tosca Musk',
    cast: ['Melanie Zanetti', 'Giulio Berruti', 'Kurt McKinney', 'Agnes Albright', 'Margaux Brooke', 'Ned Van Zandt'],
    genres: ['romance', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/oyG9TL7FcRP4EZ9Vid6uKzwdndz.jpg',
