    description_fr: 'Le professeur Gabriel Emerson apprend enfin la vérité sur l\'identité de Julia Mitchell, mais il le réalise un moment trop tard. Julia a fini d\'attendre que le spécialiste très respecté de Dante se souvienne d\'elle et ne veut plus rien avoir à faire avec lui. Gabriel peut-il regagner le cœur de Julia avant qu\'elle ne trouve l\'amour dans d\'autres bras ?',
    description_es: 'Basado en la novela más vendida de Sylvain Reynard, el profesor Gabriel Emerson se ha embarcado en un apasionado pero clandestino romance con su antigua alumna, Julia Mitchell.',
    description_tr: 'Profesör Gabriel Emerson nihayet Julia Mitchell\'in kimliği hakkındaki gerçeği öğrenir, ancak gerçekleşmesi çok geç gelir. Julia, saygın Dante uzmanının onu hatırlamasını bekliyor ve onunla daha fazla bir şey yapmak istemiyor. Gabriel başkasının kollarında sevgi bulmadan kalbini geri kazanabilir mi?',
