    id: '77', slug: 'spider-man-across-the-spider-verse', title: 'Spider-Man: Across the Spider-Verse', title_ar: 'سبايدرمان: عبر عالم العنكبوت', year: 2023,
    director: 'Kemp Powers', director_ar: 'Kemp Powers',
    cast: ['Shameik Moore', 'Hailee Steinfeld', 'Brian Tyree Henry', 'Luna Lauren Vélez', 'Jake Johnson', 'Oscar Isaac'],
    genres: ['animation', 'action', 'adventure'],
    poster_url: 'https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/9xfDWXAUbFXQK585JvByT5pEAhe.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=yFrxzaBLDQM',
    description_ar: 'بعد مرور فترة طويلة، يتلقى مايلز موراليس زيارة جديدة من جوين ستيسي، ومعًا ينطلق الثنائي في مغامرة جديدة مليئة بالمخاطر والأعداء عبر عالم العنكبوت.',
    description_en: 'After reuniting with Gwen Stacy, Brooklyn’s full-time, friendly neighborhood Spider-Man is catapulted across the Multiverse, where he encounters the Spider Society, a team of Spider-People charged with protecting the Multiverse\'s very existence. But when the heroes clash on how to handle a new threat, Miles finds himself pitted against the other Spiders and must set out on his own to save those he loves most.',
    description_fr: 'Après avoir retrouvé Gwen Stacy, Spider-Man, le sympathique héros originaire de Brooklyn, est catapulté à travers le Multivers, où il rencontre une équipe de Spider-Héros chargée d\'en protéger l\'existence. Mais lorsque les héros s\'opposent sur la façon de gérer une nouvelle menace, Miles se retrouve confronté à eux et doit redéfinir ce que signifie être un héros afin de sauver les personnes qu\'il aime le plus.',
    description_es: 'Tras reencontrarse con Gwen Stacy, el amigable vecindario de Spider-Man de Brooklyn al completo es catapultado a través del Multiverso, donde se encuentra con un equipo de Spidermans encargados de proteger su propia existencia. Pero cuando los héroes se enfrentan sobre cómo manejar una nueva amenaza, Miles se encuentra enfrentado a las otras Arañas y debe redefinir lo que significa ser un héroe para poder salvar a la gente que más quiere.',
    description_tr: 'Spider-Man: Across the Spider-Verse, radyoaktif bir örümcek tarafından ısırılmasıyla bambaşka bir dünyaya adım atıp özel yeteneklerle donanan Miles Morales\'in maceralarını konu ediyor.',
    description_de: 'Brooklyns freundliche Spinne aus der Nachbarschaft ist zurück! Nachdem sich Miles Morales aka Spider-Man gerade erst an seine Rolle gewöhnt hat, wird er bereits in sein nächstes Abenteuer und quer durch das neu entdeckte Multiversum geschleudert. Um dessen Existenz zu schützen, muss sich Spider-Man zusammen mit Gwen Stacy und einem neuen Spider-Team einem Bösewicht stellen, der mächtiger ist als alles, was ihnen bisher begegnet ist. Nur mit vereinten Kräften ist es ihnen vielleicht möglich, die Welt zu retten. Doch welche ist die richtige Vorgehensweise, um der Bedrohung zu begegnen? Als die vielen Helden der Spider-People über diese Frage aneinander geraten, muss Miles seine eigene Rolle als Held neu definieren, um die Menschen zu retten, die er liebt.',
    description_ja: '新たにスパイダーマンを継承した高校生のマイルズは、愛する人と世界を同時に救えないという事実にあらがって両方とも守り抜くと誓い、仲間と対立する。',
    description_pt: 'Miles Morales era um adolescente igual a tantos outros até descobrir ter sido picado por uma aranha e adquirir superpoderes. Fã incondicional do Homem-Aranha, resolve seguir-lhe os passos e dá início a uma vida dupla, em que se dedica a capturar vilões e salvar pessoas em perigo. Desta vez, é transportado para o Aranhaverso, um mundo onde existem outras “pessoas-aranha”, encarregues de proteger os seus mundos contra as várias manifestações do mal. Quando todos se juntam num combate épico contra um inimigo comum, Miles depara-se com um conflito inesperado.',
    rating_overall: 8.4, rating_story: 8.4, rating_acting: 8.5, rating_direction: 8.3, rating_cinematography: 8.1, rating_music: 7.9,
    imdb_rating: 8.3, rotten_tomatoes: 83,
    budget_million: 100.0,
    box_office_million: 691,
    duration: 140, language: 'EN', country: 'US',
    reviews_count: 2969, is_featured: false, release_date: '2023-05-31', tags: ['animation', 'action', 'adventure', '2023', 'powers'],
