    id: '80', slug: 'princess-mononoke', title: 'Princess Mononoke', title_ar: 'الأميرة مونونوكي', year: 1997,
    director: 'Hayao Miyazaki', director_ar: 'Hayao Miyazaki',
    cast: ['Yoji Matsuda', 'Yuriko Ishida', 'Yuko Tanaka', 'Kaoru Kobayashi', 'Masahiko Nishimura', 'Tsunehiko Kamijô'],
    genres: ['adventure', 'drama', 'animation'],
    poster_url: 'https://image.tmdb.org/t/p/w500/cMYCDADoLKLbB83g4WnJegaZimC.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/gl0jzn4BupSbL2qMVeqrjKkF9Js.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=I1dHzoRl0sQ',
    description_ar: 'كانت هنالك قرية صغيرة لا تكاد ترى يعيش فيها أشيتاكا بهدوء ونعيم. وهذه القبليه هي من القبائل التي قام الإمبراطور بنفيها وحكم عليها بنسيان إلى الأبد وبذلك تنفى هذه القبيلة وتختفي عن الأنظار وهكذا لم يعرف الناس بهم ولم يعرفوا قدرهم ومن قوانين هذه القبيلة أن أي شخص لا يمكنه مغادرتها والذي يغادرها لا يعود أبداً. أشيتاكا هو أميرهم وهو يقوم بحمايتهم جميعاً من المصاعب التي تواجههم في أحد الايام بينما كان أشيتاكا في الجوار مع غزاله الأحمر, صدر صوت غريب يشبه جلبه وفجأة يظهر حيوان غريب كبير وبذلك تتغير حياة أشيتاكا للأبد منذ تلك اللحظة.',
    description_en: 'Ashitaka, a prince of the disappearing Emishi people, is cursed by a demonized boar god and must journey to the west to find a cure. Along the way, he encounters San, a young human woman fighting to protect the forest, and Lady Eboshi, who is trying to destroy it. Ashitaka must find a way to bring balance to this conflict.',
    description_fr: 'Parti en quête d\'un remède, un prince affecté par un mal fatal se retrouve dans une contrée où se livre une bataille entre une ville minière et les animaux de la forêt.',
    description_es: 'Tras sufrir el ataque de un monstruoso jabalí maldito, el joven Ashitaka emprende el camino en busca de la cura que detenga la infección. Mientras, los humanos están acabando con los bosques y los dioses convertidos en temibles bestias hacen todo lo posible por protegerlo encabezados por Mononoke, una princesa guerrera. Ashikata deberá escoger bando y decidir si ayudar a los hombres o las deidades intentando detener la maldición de su herida que se extiende por su cuerpo sin cuartel.',
    description_tr: 'Köyünde huzur dolu bir yaşamı olan Ashitaka, bir gün ormandan kötü bir varlığın gelmekte olduğu fark eder. Ormanın sınırından hızla çıkan Orman Tanrısı, değdiği her şeyi yok ederek ilerlemektedir. Köyünden küçük bir kızı kurtarmak için, canavara dönüşmüş olan Orman Tanrısı\'na saldıran Ashitaka, mücadele sonunda canavarı öldürür ama ölümcül bir yara alarak lanetlenir.Bu lanetten kurtulmak için bir yol aramak üzere köyden ayrılan Ashitaka, kendisine yardım edebileceğini umduğu Ormanın Ruhu\'nu aramaya başlar. Ancak Ormanın Ruhu\'nu arayan başkaları da vardır: Lady Eboshi ve Irontown sakinleri. Lady Eboshi ve Prenses Mononoke arasındaki savaşta kazanan olmadığını ve hem insanların hem de doğanın zarar gördüğünü fark eden Ashitaka, onları durdurmaya çalışacaktır.',
    description_de: 'Japan im frühen Mittelalter. Der junge Krieger Ashitaka tötet in Notwehr einen dämonischen Eber und wird darauf mit einem Fluch belegt. Auf der Suche nach Heilung durchstreift Ashitaka das Land und stößt schließlich nahe einer befestigten Hüttensiedlung, die sich tief in das einst idyllische Land um einen Heiligen Berg frisst, auf die von Wölfen großgezogene Kriegerin San, genannt Mononoke. Obwohl San einen Krieg für die Natur wider ihre Zerstörer führt, verliebt sie sich in Ashitaka.',
    description_ja: '山里に住む若者アシタカは、怒りと憎しみにより“タタリ神”と化した猪神から呪いをかけられてしまう。呪いを解く術を求めて旅に出るアシタカはやがて、西方の地で“タタラ”の村にたどり着く。エボシ御前が率いるその村では、鉄を造り続けていたが、同時にそれは神々の住む森を破壊することでもあった。そして、そんなタタラ達に戦いを挑むサンの存在をアシタカは知る。人の子でありながら山犬に育てられた彼女は“もののけ姫”と呼ばれていた。',
    description_pt: 'Ashitaka é o jovem guerreiro do clã Emishi que é amaldiçoado ao defender a sua aldeia de um demónio criado pela violência humana. Assim, viaja até à região controlada pelo clã Tatara na esperança de compreender a maldição que lhe fora posta, antes que esta o mate. O que Ashitaka vai encontrar é um conflito entre os humanos e os deuses da floresta. Apanhado no meio do conflito, Ashitaka conhece San, a Princesa Mononoke. Criada por lobos, Mononoke fará tudo o que puder para acabar com os humanos que ameaçam a floresta',
    rating_overall: 8.4, rating_story: 8.4, rating_acting: 8.5, rating_direction: 8.3, rating_cinematography: 8.1, rating_music: 7.9,
    imdb_rating: 8.3, rotten_tomatoes: 83,
    budget_million: 23.5,
