    reviews_count: 5550, is_featured: false, release_date: '1968-12-21', tags: ['drama', 'western', '1968', 'leone'],
    pros_ar: ['عمق درامي استثنائي', 'أداء تمثيلي رائع', 'قصة إنسانية مؤثرة'],
