    id: '92', slug: 'paths-of-glory', title: 'Paths of Glory', title_ar: 'دروب المجد', year: 1957,
    director: 'Stanley Kubrick', director_ar: 'Stanley Kubrick',
    cast: ['Kirk Douglas', 'Ralph Meeker', 'Adolphe Menjou', 'George Macready', 'Wayne Morris', 'Richard Anderson'],
    genres: ['history', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/p7OHwomA8UOhe3EhckF2IetBTh9.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/eTZkq5tI58Ec76AwPf1HOUoKtky.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=FESvZ0HG2p4',
    description_ar: 'ضابط قائد يدافع عن ثلاثة أكباش فداء أثناء محاكمتهم لهجوم فاشل وقع داخل الجيش الفرنسي عام 1916.',
    description_en: 'A commanding officer defends three scapegoats on trial for a failed offensive that occurred within the French Army in 1916.',
    description_fr: 'En 1916, durant la Première Guerre mondiale, le général français Broulard ordonne au général Mireau de lancer une offensive suicidaire contre une position allemande imprenable, surnommée la « Fourmilière ». Au moment de l\'attaque, les soldats tombent par dizaines et leurs compagnons, épuisés, refusent d\'avancer…',
    description_es: 'Primera Guerra Mundial (1914-1918). En 1916, en Francia, el general Boulard ordena la conquista de una inexpugnable posición alemana y encarga esa misión al ambicioso general Mireau. El encargado de dirigir el ataque será el coronel Dax. La toma de la colina resulta un infierno, y el regimiento emprende la retirada hacia las trincheras. El alto mando militar, irritado por la derrota, decide imponer al regimiento un terrible castigo que sirva de ejemplo a los demás soldados.',
    description_tr: 'Filmin konusu Fransız ordusundaki komuta kademesinin savaşmak istemeyen askerlere gözdağı verip korkutmak amacıyla suçsuz askerleri kurşuna dizmesidir. Fransız Ordusu da savaş sırasında diğer müttefik orduları gibi korkaklık suçundan dolayı infazlar gerçekleştirmiştir. Ancak filmin merkezinde duran sorun, verilen emre karşı gelerek saldırıya geçmeyen tüm cephenin yerine rastgele seçilen askerlerin kurşuna dizilmesidir. Bu tür cezalandırma tarihte Romalılar tarafından yaygın olarak uygulanmıştır. Onuncunun cezalandırılması olarak dilimize çevrilebilecek decimation cezasında suçlular arasından her on kişiden bir tanesi öldürülerek ceza uygulanır. Bu ceza Fransız Ordusunda, Flanders yakınlarında 15 Aralık 1914 tarihinde geri çekilen Cezayir Alayı 8.Tabur 10. Bölük askerleri hücum emrine uymayınca uygulanmıştır...',
    description_de: 'Frankreich im Ersten Weltkrieg. Die Ruhmsucht des General Mireau wird für seine Soldaten zum tödlichen Verhängnis: Er gibt Schießbefehl auf verloren geglaubte Teile seiner Bastion und hält Kriegsgericht über die eigenen Männer. Nur der couragierte Colonel Dax wagt es, sich dem machtgierigen Mireau entgegen zu stellen. Doch im Krieg kann es keine Gewinner geben.',
    description_ja: '第一次世界大戦、フランスの最大の課題はドイツ軍の撃退だった。そんな中、ダックス大佐はドイツ軍の要所を攻略する命令を受ける。だが、兵士たちの疲労を知るダックスは、現在攻撃を仕掛ければ兵士たちが壊滅的打撃を受けると抗議する。が、軍上層部は無視、作戦は実行される。フランス軍は大敗し、ダックスは責任を問われ軍法会議にかけられる。',
    description_pt: 'Quando soldados franceses nas trincheiras da Primeira Guerra Mundial recusam-se a continuar um ataque aparentemente impossível de se vencer, seus superiores resolvem levá-los à corte marcial, onde poderão ser julgados à morte.',
    rating_overall: 8.4, rating_story: 8.4, rating_acting: 8.5, rating_direction: 8.3, rating_cinematography: 8.1, rating_music: 7.9,
