    id: '103', slug: 'klaus', title: 'Klaus', title_ar: 'كلاوس', year: 2019,
    director: 'Sergio Pablos', director_ar: 'Sergio Pablos',
    cast: ['Jason Schwartzman', 'J.K. Simmons', 'Rashida Jones', 'Joan Cusack', 'Norm Macdonald', 'Will Sasso'],
