    id: '106', slug: 'five-feet-apart', title: 'Five Feet Apart', title_ar: 'على بعد خمسة أقدام', year: 2019,
    director: 'Justin Baldoni', director_ar: 'Justin Baldoni',
    cast: ['Haley Lu Richardson', 'Cole Sprouse', 'Moisés Arias', 'Kimberly Hébert Gregory', 'Parminder Nagra', 'Claire Forlani'],
    genres: ['romance', 'drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/kreTuJBkUjVWePRfhHZuYfhNE1T.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/27ZkYMWynuK2qiDP6awc3MsCaOs.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=24YrEAGF32M',
    description_ar: 'ستيلا جرانت فتاة في السابعة عشر من عمرها، تلازم المستشفى طوال الوقت بسبب إصابتها بمرض التليف الكيسي، مما يجعل حياتها مليئة بالقيود والروتين، وفي يوم تقابل ويل نيومان المصاب هو اﻷخر بالتليف الكيسي، ورغم انجذابهما لبعضهما البعض، عليهما البقاء على مسافة آمنة.',
    description_en: 'Seventeen-year-old Stella spends most of her time in the hospital as a cystic fibrosis patient. Her life is full of routines, boundaries and self-control — all of which get put to the test when she meets Will, an impossibly charming teen who has the same illness. There\'s an instant flirtation, though restrictions dictate that they must maintain a safe distance between them. As their connection intensifies, so does the temptation to throw the rules out the window and embrace that attraction.',
    description_fr: 'Stella Grant, dix-sept ans, est atteinte par la fibrose kystique. Elle a passé une grande partie de sa vie entre les quatres murs de sa chambre d\'hôpital. C\'est dans ce contexte, qu\'elle tombe amoureuse de Will Newman, également atteint de la mucoviscidose. Leurs états de santé respectifs les empêchent de s\'approcher trop près l\'un de l\'autre. De plus, Stella doit tenter de raisonner son amoureux qui ne veut plus prendre ses traitements médicaux.',
    description_es: 'Will y Stella son dos adolescentes que padecen fibrosis quística y están ingresados en el hospital para tratarse. Aunque ambos tratan de refugiarse en su propio mundo, de forma inevitable acaban enamorándose. La pareja deberá luchar para mantener viva su relación, con una única regla: separarse con una distancia de alrededor de dos metros para evitar que ambos se puedan contagiar. Sin embargo, la vida de ambos estará en peligro.',
    description_tr: 'İki hasta gencin hastanede yollarının kesişmesi ile değişen yaşamlarını konu ediyor. Stella Grant, 17 yaşında olan bir genç kızdır. Bilgisayarına bağlı bir hayat süren Stella, yaşıtları gibi gezip dolaşmak yerine zamanını çoğunu hastanede geçirmek zorundadır. Kistik fibrozis hastası olan genç kız hayatını rutinler, sınırlamalar ve kendi kendini kontrol etmekle geçirir. Fakat genç kızın hayatı  Will Newman ile tanışmasıyla bambaşka bir hal alır. Birbirlerinden etkilenmeye başlayan gençlerin önünde büyük bir engel vardır. Will de Stella gibi hastadır ve hastalıkları nedeniyle hayatlarına konulan sınırlamalar aralarına mesafe koymalarını gerektirir. Ancak onlar birlikte vakit geçirmeye devam ettikçe sınırlamaların dışına çıkmaya başlarlar.',
    description_de: 'Stella ist eine 17-Jährige, wie sie im Buche steht: Ihr Smartphone gibt sie nicht aus der Hand und am liebsten chattet sie mit ihren Freunden. Nur Platz zum Träumen bleibt ihr nicht, denn anders als normale Teenager, verbringt sie die meiste Zeit unter strenger Beobachtung im Krankenhaus. Stella leidet an der unheilbaren Erbkrankheit Mukoviszidose und ihre wichtigste Regel lautet: Komm keinem Mitpatienten näher als 4 Schritte, denn er könnte dich mit seinen Bakterien schwächen und schlimmstenfalls töten.',
    description_ja: 'Seventeen-year-old Stella spends most of her time in the hospital as a cystic fibrosis patient. Her life is full of routines, boundaries and self-control — all of which get put to the test when she meets Will, an impossibly charming teen who has the same illness. There\'s an instant flirtation, though restrictions dictate that they must maintain a safe distance between them. As their connection intensifies, so does the temptation to throw the rules out the window and embrace that attraction.',
    description_pt: 'Uma rapariga e um rapaz adolescentes, ambos a padecer de fibrose quística, conhecem-se no hospital, onde são acompanhados por causa da sua doença, e apaixonam-se.',
    rating_overall: 8.3, rating_story: 8.3, rating_acting: 8.4, rating_direction: 8.2, rating_cinematography: 8, rating_music: 7.8,
    imdb_rating: 8.2, rotten_tomatoes: 82,
    budget_million: 7.0,
