    id: '114', slug: 'the-shining', title: 'The Shining', title_ar: 'البريق', year: 1980,
    director: 'Stanley Kubrick', director_ar: 'Stanley Kubrick',
    cast: ['Jack Nicholson', 'Shelley Duvall', 'Danny Lloyd', 'Scatman Crothers', 'Barry Nelson', 'Philip Stone'],
    genres: ['horror', 'thriller'],
    poster_url: 'https://image.tmdb.org/t/p/w500/uAR0AWqhQL1hQa69UDEbb2rE5Wx.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/mmd1HnuvAzFc4iuVJcnBrhDNEKr.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=FZQvIJxG9Xs',
    description_ar: 'يقبل جاك تورانس وظيفة تصريف أعمال في فندق Overlook ، حيث يجب أن يعيش مع زوجته ويندي وابنهما داني في عزلة عن بقية العالم في الشتاء. لكنهم ليسوا مستعدين للجنون الكامن بداخلهم.',
    description_en: 'Jack Torrance accepts a caretaker job at the Overlook Hotel, where he, along with his wife Wendy and their son Danny, must live isolated from the rest of the world for the winter. But they aren\'t prepared for the madness that lurks within.',
    description_fr: 'Jack Torrance, gardien d’un hôtel fermé l’hiver, sa femme et son fils Danny s’apprêtent à vivre de longs mois de solitude. Danny, qui possède un don de médium, le «Shining», est effrayé à l’idée d’habiter ce lieu, théâtre marqué par de terribles événements passés…',
    description_es: 'Jack Torrance se traslada, junto a su mujer y a su hijo, al impresionante hotel Overlook, en Colorado, para encargarse del mantenimiento del mismo durante la temporada invernal, en la que permanece cerrado y aislado por la nieve. Su idea es escribir su novela al tiempo que cuida de las instalaciones durante esos largos y solitarios meses de invierno, pero desde su llegada al hotel, Jack comienza a padecer inquietantes transtornos de personalidad, al mismo tiempo que en el lugar comienzan a suceder diversos fenómenos paranormales.',
    description_tr: 'Cinnet, yazar Jack Torrance’ın, kış sezonunda kapalı olan Overlook Oteli’nin bakımını üstlenerek, ailesiyle birlikte otele taşınması sonrasında gelişen metafiziksel olayları konu alır. Jack’in doğaüstü sezgilere sahip olan küçük oğlu, zamanla otelin içerisinde yalnız olmadıklarını, geçmiş ve gelecekten gelen hayaletlerle birlikte yaşadıklarını görür ve ailesini buna inandırmaya çalışır. Aile bir kar fırtınası sebebiyle dağda konuşlanan bu otelde mahsur kaldığındaysa Jack doğaüstü varlıklar tarafından ele geçirilir ve yavaş yavaş aklını kaybetmeye başlar.',
    description_de: 'Der ehemalige Lehrer und Schriftsteller Jack Torrance übernimmt die Stelle des Hausverwalters in einem mit einem Mythos behafteten Berghotel in Colorado. Während der Wintermonate soll Jack das alleinstehende Gebäude im Auge behalten. Der Familienvater sieht darin die perfekte Gelegenheit, in Ruhe seinen Roman zu beenden. Auch seine Frau Wendy freut sich auf die Zeit im abgeschiedenen Hotel. Nur der sechsjährige Sohn Danny hat bei der ganzen Sache so seine Bedenken. Es dauert nicht lange bis die dunklen Vorahnungen und blutigen Visionen, die dem Jungen schon kurz nach dem Einzug das erste mal begegnen, zur Realität werden: Vater Jack beginnt immer mehr, den Verstand zu verlieren. Mit einer Axt bewaffnet, beginnt der wahnsinnig Gewordene die Jagd auf seine Familie.',
    description_ja: '冬の間は豪雪で閉鎖されるホテルの管理人職を得た小説家志望のジャック・トランスは、妻のウェンディーと心霊能力のある息子ダニーとともにホテルへやってくる。そのホテルでは、かつて精神に異常をきたした管理人が家族を惨殺するという事件が起きており、当初は何も気にしていなかったジャックも、次第に邪悪な意思に飲みこまれていく。',
    description_pt: 'O escritor Jack Torrance chega ao elegante e isolado Overlook Hotel, com a sua mulher e o filho pequeno. O seu objectivo é escrever um livro, ao mesmo tempo que serve de guarda de Inverno de um espaço que costuma ficar sem acessos nas estações frias. Torrance nunca tinha estado lá - ou será que tinha? A resposta vai ser encontrada num fantasmagórico turbilhão de loucura e de morte.',
    rating_overall: 8.3, rating_story: 8.3, rating_acting: 8.4, rating_direction: 8.2, rating_cinematography: 8, rating_music: 7.8,
    imdb_rating: 8.2, rotten_tomatoes: 82,
    budget_million: 19.0,
    box_office_million: 45,
