    id: '116', slug: 'the-help', title: 'The Help', title_ar: 'الخادمة', year: 2011,
    director: 'Tate Taylor', director_ar: 'Tate Taylor',
    cast: ['Emma Stone', 'Viola Davis', 'Bryce Dallas Howard', 'Octavia Spencer', 'Jessica Chastain', 'Ahna O\'Reilly'],
    genres: ['drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/3kmfoWWEc9Vtyuaf9v5VipRgdjx.jpg',
    backdrop_url: 'https://image.tmdb.org/t/p/original/wyvUmyzqGOBDyqLHRSukGDjI7bH.jpg',
    trailer_url: 'https://www.youtube.com/watch?v=3eajzW3XW7Q',
    description_ar: 'كاتبة تتحول حياتها وتنقلب رأسًا على عقب عندما تقرر مقابلة بعض النساء السود بولاية ميسسيبي واللاتي قضين حياتهن في رعاية اﻷسر فتتوغل في حياتهن الشخصي في محاولة منها للتعاون معهن، وتتوالى الأحداث مع سرد كل منهن لقصتها.',
    description_en: 'Aibileen Clark is a middle-aged African-American maid who has spent her life raising white children and has recently lost her only son; Minny Jackson is an African-American maid who has often offended her employers despite her family\'s struggles with money and her desperate need for jobs; and Eugenia "Skeeter" Phelan is a young white woman who has recently moved back home after graduating college to find out her childhood maid has mysteriously disappeared. These three stories intertwine to explain how life in Jackson, Mississippi revolves around "the help"; yet they are always kept at a certain distance because of racial lines.',
    description_fr: 'Dans la petite ville de Jackson, Mississippi, durant les années 60, trois femmes que tout devait opposer vont nouer une incroyable amitié. Elles sont liées par un projet secret qui les met toutes en danger, l’écriture d’un livre qui remet en cause les conventions sociales les plus sensibles de leur époque. De cette alliance improbable va naître une solidarité extraordinaire. À travers leur engagement, chacune va trouver le courage de bouleverser l’ordre établi, et d’affronter tous les habitants de la ville qui refusent le vent du changement…',
    description_es: 'Mississippi, años 60. Skeeter es una joven sureña que regresa de la universidad decidida a convertirse en escritora. Su llegada altera la vida de la ciudad e incluso la de sus amigos porque se ha propuesto entrevistar a las mujeres negras que se han pasado la vida al servicio de las grandes familias sufriendo todas las formas de discriminación racial.',
    description_tr: '1960\'lı yılların Mississippi eyaletinde geçen filmde Eugenie “Skeeter” Phelan, iyi bir eğitim alarak mezun olmuş bir genç kızdır ve diğer yaşıtı kız arkadaşları gibi evlenip, çocuk yapmak yerine kendine meslek edinmek ister. Bir yazar olmak isteyen Skeeter, annesinin “evlenip yuva kurması” gibi beklentilerini de boşa çıkartarak yerel bir gazetede küçük bir köşe sahibi olur. Ev işlerinde püf noktalarını yazdığı bu minik köşe için en yakın arkadaşının siyahi hizmetçisi Aibileen Clark\'tan yardım ister ve böylece kendisini sıradışı bir projeye başlarken bulur. Bu gizli projede dokunaklı hikayeler yazmaya başlayınca ona bu ilhamı veren hizmetçi Aibileen ve arkadaşı Minny\'nin anlattığı gerçek hikayelerinden çok etkilenir ve bu siyahi hizmetçilerin yaşadığı insanlık dışı muameleyi ortadan kaldırmayı kafasına koyar.',
    description_de: '1962 kehrt die junge Skeeter von ihrem Collegestudium zurück in ihre Südstaaten-Heimatstadt. Ihre alten Freundinnen haben viel Freizeit. Denn ihre Babys und Haushalte werden von farbigen Hausangestellten versorgt. Als eine von ihnen ein Gesetz einbringen will, dass Schwarze separate Toiletten benutzen sollen, ist Skeeter dermaßen schockiert, dass sie beschließt, die Hausmädchen in ihrer Umgebung zu interviewen, um ihre Seite zu dokumentieren. Zunächst fällt es ihr schwer, das Eis zu brechen, doch letztlich erhält sie die volle Unterstützung von Aibileen und Minny.',
    description_ja: 'アメリカ・ミシシッピ州。1960年代当時、白人家庭でメイドとして働く黒人女性は“ヘルプ”と呼ばれていた。作家志望のスキーター（エマ・ストーン）はメイドの置かれた立場に疑問を抱き、彼女たちにインタビューをすることに。仕事を失うことを恐れて、皆が口をつぐむ中、一人の女性の勇気が社会を揺るがすことになる。',
    description_pt: 'Três mulheres extraordinárias e muito diferentes no Mississippi durante os anos 60, que construíram uma improvável amizade em torno de um projecto secreto que quebra todas as regra sociais e as coloca a todas em risco. Desta inesperada aliança, emerge uma admirável irmandade, incutindo-lhes uma coragem para transcenderem os próprios limites, e a consciencialização de que às vezes esses limites existem para serem ultrapassados – mesmo que isso signifique que todos na cidade tenham de confrontar-se com os tempos de mudança.',
    rating_overall: 8.3, rating_story: 8.3, rating_acting: 8.4, rating_direction: 8.2, rating_cinematography: 8, rating_music: 7.8,
    imdb_rating: 8.2, rotten_tomatoes: 82,
