    trailer_url: 'https://www.youtube.com/watch?v=tnCkn5xD2jg',
    description_ar: 'Earth is decimated after intergalactic tyrant Darkseid has devastated the Justice League in a poorly executed war by the DC Super Heroes. Now the remaining bastions of good – the Justice League, Teen Titans, Suicide Squad and assorted others – must regroup, strategize and take the war to Darkseid in order to save the planet and its surviving inhabitants.',
    description_en: 'Earth is decimated after intergalactic tyrant Darkseid has devastated the Justice League in a poorly executed war by the DC Super Heroes. Now the remaining bastions of good – the Justice League, Teen Titans, Suicide Squad and assorted others – must regroup, strategize and take the war to Darkseid in order to save the planet and its surviving inhabitants.',
    description_fr: 'Suite à ses deux invasions ratées de la Terre,  Darkseid a été sur un chemin de guerre, conquérant d\'innombrables mondes. À la Watchtower, la Justice League , rejointe par de nouveaux membres John Constantine et son amant Zatanna , fait un plan pour contrer son invasion à travers l\'univers. Cependant, à leur insu, Darkseid les regarde à travers la technologie de Victor Stone . La Ligue se dirige vers Apokolips tandis que les Teen Titans restent sur Terre en tant que "garde à domicile". A leur arrivée, la Ligue est attaquée par des "Paradooms"; hybrides génétiques de Parademons et Doomsday . Pendant l\'attaque, plusieurs héros sont tués. Darkseid démantèle Cyborg - qui permet à Shazam de s\'échapper - et remplace ses pièces par la technologie apokoliptienne, asservit Diana , Starfire , Hawkman , Mera et Martian Manhunter pour devenir ses Furies mécanisées, place Batman dans son contrôle mental, faisant de lui son bras droit, et injecte à Clark Kent du liquide de Kryptonite, le dépower...',
    description_es: 'Culminando seis años de una aventura que comenzó con el lanzamiento de Justice League: War en 2014, Justice League Dark: Apokolips War presenta un planeta Tierra totalmente devastado por el tirano intergaláctico Darkseid en el que los superhéroes apenas han podido hacer frente a la guerra. Los últimos bastiones de guerreros que aún quedan en pie deben reagruparse para crear una estrategia que les permita enfrentarse a Darkseid con el propósito de salvar al planeta y a sus pocos supervivientes. Esta es la guerra que acabará con todas las guerras.',
    description_tr: 'Dünya’nın Darkseid’in eline geçmesinden sonra, kalan süper kahramanlar, gezegeni ve hayatta kalanlarını bir kez ve herkes için kurtarma şansı için yeniden toplanmak ve savaşı Darkseid’e götürmek zorunda kalacaklardır.',
    description_de: 'Im Zeichentrickfilm Justice League Dark: Apokolips War kehrt Bösewicht Darkseid mit seiner Armee auf die Erde zurück, um erneut gegen die Justice League und ihre Verbündeten zu kämpfen. Neben der Justice League Dark rund um die Magier John Constantine und Zatanna sind zahlreiche andere bekannte DC-Charaktere in den Krieg gegen Darkseid involviert.',
    description_ja: 'Earth is decimated after intergalactic tyrant Darkseid has devastated the Justice League in a poorly executed war by the DC Super Heroes. Now the remaining bastions of good – the Justice League, Teen Titans, Suicide Squad and assorted others – must regroup, strategize and take the war to Darkseid in order to save the planet and its surviving inhabitants.',
    description_pt: 'A conclusão de uma jornada, iniciada em Liga da Justiça: Guerra, de 2014, "Liga da Justiça Sombria: Guerra de Apokolips" lida agora com uma Terra dizimada após uma invasão do imperador de Apokolips, Darkseid, que derrota toda a Liga da Justiça após uma tentativa de ataque malsucedidos dos maiores heróis da DC. Agora, os sobreviventes restantes da Liga da Justiça, Jovens Titãs, Esquadrão Suicida e outros heróis e vilões precisam se unir, montar uma estratégia e levar a guerra a Darkseid, em um levante final para salvar o planeta e seus habitantes. Essa é a guerra para acabar com todas as guerras, e só os vitoriosos poderão viver para aproveitar os espólios.',
