    trailer_url: 'https://www.youtube.com/watch?v=qdPw9x9h5CY',
    description_ar: 'جندي في الحرب العالمية الثانية تحول إلى جندي أمريكي. يحقق المارشال تيدي دانيلز في اختفاء مريض من مستشفى بسبب الجنون الإجرامي ، لكن جهوده تتعرض للخطر بسبب رؤاه المزعجة وأيضًا بسبب طبيب غامض.',
    description_en: 'World War II soldier-turned-U.S. Marshal Teddy Daniels investigates the disappearance of a patient from a hospital for the criminally insane, but his efforts are compromised by troubling visions and a mysterious doctor.',
    description_fr: 'En 1954, le marshal Teddy Daniels et son coéquipier Chuck Aule sont envoyés enquêter sur l’île de Shutter Island, dans un hôpital psychiatrique où sont internés de dangereux criminels. L’une des patientes, Rachel Solando, a inexplicablement disparu. Comment la meurtrière a‐t‐elle pu sortir d’une cellule fermée de l’extérieur ? Le seul indice retrouvé dans la pièce est une feuille de papier sur laquelle on peut lire une suite de chiffres et de lettres sans signification apparente. Œuvre cohérente d’une malade, ou cryptogramme ?',
    description_es: 'Verano de 1954. Los agentes judiciales Teddy Daniels y Chuck Aule son destinados a una remota isla del puerto de Boston para investigar la desaparición de una peligrosa asesina recluida en el hospital psiquiátrico Ashecliffe, un centro penitenciario para criminales perturbados dirigido por el siniestro doctor John Cawley. Pronto descubrirán que el centro guarda muchos secretos, y que la isla esconde algo más peligroso que los pacientes.',
    description_tr: 'Amerikan Marşal\'ı Teddy Daniels, (DiCaprio) Shutter Island’daki cani delilerin bulunduğu akıl hastanesine geldiğinde, rutin bir soruşturma şeytani bir nitelik kazanır. Soruşturma ilerledikçe, Teddy adaya dair çok daha şaşırtıcı ve çok daha korkutucu gerçeklerle karşılaşır ve bazı yerlerin insanın peşini hiç bırakmadığını öğrenir.',
    description_de: '1954 soll der U.S. Marshall Teddy Daniels das Verschwinden eines Patienten aus dem Bostoner Shutter Island Ashecliffe Hospital aufklären. Er hat sich aus persönlichen Gründen um diesen Auftrag bemüht, aber schon bald muss er sich fragen, ob er nicht durch die Ärzte manipuliert wurde, deren Methoden von unethisch über illegal bis skrupellos gehen. Teddys scharfsinnige Ermittlungsmethoden führen rasch zu einer vielversprechenden Spur, aber das Hospital verweigert ihm Zugriff auf Informationen, die den Fall erhellen könnten. Als ein Hurrikan die Verbindung zum Festland unterbricht, "entkommen" weitere gefährliche Kriminelle in dem Chaos und die verwirrenden Hinweise mehren sich, so dass Teddy an allem zu zweifeln beginnt - seinem Gedächtnis, seinem Partner und sogar seinem eigenen Verstand.',
