    description_tr: 'Miguel, ailesinin nesiller boyu süren yasağına rağmen idolü Ernesto de la Cruz gibi başarılı bir müzisyen olmanın hayalini kuruyordur. Çaresizce yeteneğini kanıtlamaya çalışan Miguel, kendini etkileyici ve renkli Ölüler Şehri\'nde bir dizi gizemli olay zincirini takip ederken bulur. Bu sırada çekici bir oyunbaz olan Hector\'la tanışır ve birlikte Miguel\'in aile geçmişindeki asıl hikâyeyi ortaya çıkartacak olağanüstü bir yolculuğa çıkarlar.',
    description_de: 'Miguel ist zwölf Jahre alt und ein großer Fan von Musik – aber leider hasst seine Schusterfamilie alles, was mit Tönen und Instrumenten zu tun hat. Miguels Ururgroßvater verließ damals seine Frau und Tochter, um Musiker zu werden, seitdem fühlen sich die Riveras durch Musik verflucht. Doch Familie hin oder her – Miguel will seinem Idol, dem Sänger Ernesto de la Cruz, trotzdem nacheifern. Aus Versehen kommt er dabei ins Reich der Toten und betritt dadurch einen wunderschönen Ort, an dem er die Seelen seiner toten Verwandten trifft. Miguels Ururgroßmutter Imelda ist darunter, und das nette Schwindler-Skelett Hector. Zusammen suchen Skelett und Junge im Totenreich nach de la Cruz, wobei allerdings die Zeit drängt: Zu lange darf Miguel nicht in der Unterwelt bleiben…',
